#!/usr/bin/env node
/* global console, process */
// Presentation fidelity vectors are generated by the Java tests (java/src/test/resources/fx/vectors/, on
// FX_DUMP_VECTORS=1) and mirrored here (test/fx/vectors/) so each edition's CI is self-contained
// (docs/architecture/animation.md §3.4). Part of `npm run lint`.
//   node tools/sync-fx-vectors.mjs          # check: every Java vector has a byte-identical Bedrock copy
//   node tools/sync-fx-vectors.mjs --write  # copy Java → Bedrock (never the other way)
// A Bedrock-only vector file (no Java twin) is an error too: vectors are born in Java. Without a ../java checkout
// (e.g. a Bedrock-only export) the check is skipped.
import fs from 'node:fs';
import path from 'node:path';
import { fileURLToPath } from 'node:url';

const ROOT = path.resolve(path.dirname(fileURLToPath(import.meta.url)), '..');
const SRC = path.resolve(ROOT, '../java/src/test/resources/fx/vectors');
const DST = path.join(ROOT, 'test/fx/vectors');
if (!fs.existsSync(SRC)) {
  console.info('no ../java checkout: vector sync skipped');
  process.exit(0);
}
const write = process.argv.includes('--write');
const list = (dir) => (fs.existsSync(dir) ? fs.readdirSync(dir).filter((n) => n.endsWith('.json')).sort() : []);
const problems = [];
for (const f of list(SRC)) {
  const a = fs.readFileSync(path.join(SRC, f));
  const dst = path.join(DST, f);
  if (fs.existsSync(dst) && fs.readFileSync(dst).equals(a)) continue;
  if (write) {
    fs.mkdirSync(DST, { recursive: true });
    fs.writeFileSync(dst, a);
    console.info(`synced ${f}`);
  } else problems.push(`${fs.existsSync(dst) ? 'out of sync' : 'missing in bedrock/test/fx/vectors'}: ${f}`);
}
for (const f of list(DST)) if (!fs.existsSync(path.join(SRC, f))) problems.push(`no Java source for bedrock/test/fx/vectors/${f} (vectors are generated by the Java tests)`);
if (problems.length) {
  for (const p of problems) console.error(p);
  console.error('fix: regenerate in Java (FX_DUMP_VECTORS=1 ./gradlew test), then run npm run sync:vectors -- --write');
  process.exit(1);
}
console.info(`fx vectors in sync (${list(SRC).length} file(s))`);
